m.Entity<QuyetToanHopDong>(e => {
            e.ToTable("QuyetToanHopDong",t=>{
                t.HasCheckConstraint("CK_QuyetToanHopDong_Version","PhienBan=1 AND LEN(MaBam)=64");
                t.HasCheckConstraint("CK_QuyetToanHopDong_Money","TienThue>=0 AND PhiGiaHan>=0 AND PhiTraTre>=0 AND BoiThuong>=0 AND ThuePhiDaThu>=0 AND CocDaThu>=0 AND CocKhauTru>=0 AND CocKhauTru<=CocDaThu AND ConPhaiThuBanDau>=0 AND HoanCocBanDau>=0 AND HoanKhacBanDau>=0 AND TongNghiaVu=TienThue+PhiGiaHan+PhiTraTre+BoiThuong AND ThuePhiDaThu+CocDaThu+ConPhaiThuBanDau=TongNghiaVu+HoanCocBanDau+HoanKhacBanDau");
            }); e.HasKey(x => x.Id); e.HasIndex(x => x.MaHopDong).IsUnique();
            e.HasAlternateKey(x=>new{x.Id,x.MaHopDong});
            e.HasAlternateKey(x=>new{x.Id,x.PhienBan,x.MaBam});
            e.Property(x => x.Id).HasMaxLength(20).IsUnicode(false);
            e.Property(x => x.MaHopDong).HasMaxLength(20).IsUnicode(false);
            e.Property(x => x.MaBienBan).HasMaxLength(20).IsUnicode(false);
            e.Property(x => x.MaBam).HasMaxLength(64).IsUnicode(false);
            e.HasOne<HopDong>().WithOne().HasForeignKey<QuyetToanHopDong>(x => x.MaHopDong).OnDelete(DeleteBehavior.Restrict);
            e.HasOne<BienBanNhanTra>().WithOne().HasForeignKey<QuyetToanHopDong>(x => new{x.MaBienBan,x.MaHopDong})
                .HasPrincipalKey<BienBanNhanTra>(x=>new{x.Id,x.MaHopDong}).OnDelete(DeleteBehavior.Restrict);
            Actor(e, nameof(QuyetToanHopDong.NguoiChot));
            foreach (var p in typeof(QuyetToanHopDong).GetProperties().Where(p => p.PropertyType == typeof(decimal)))
                e.Property(p.Name).HasPrecision(18, 2);
        })

